            BookingPersonOption("nearest", "Whoever is nearest and cleared", "The nearest nurse whose badge is current takes the visit. You are told who before anybody sets off."),
            BookingPersonOption("previous", "The nurse you saw last time", "Offered only while her badge is still current. If it is not, the reason is shown instead of her name."),
            BookingPersonOption("named", "A nurse you choose by name", "From the nurses whose badge is current, nearest first.")
