    /** What happens to a visit asked of one nurse by name when she cannot take it in Care's offer window. */
    object Fallback {
        /** Access's setting named-nurse-fallback. A proposal nobody has decided. A default an admin may change on the web; this app has no admin surface and uses it as written here. */
        const val inForce = "patient-chooses"
        const val heading = "If {nurse} cannot take it within {minutes} minutes"
        val rules = listOf(
            BookingFallbackRule("patient-chooses", true, true, null, "You choose now what happens if {nurse} cannot take this visit within {minutes} minutes of it reaching her."),
            BookingFallbackRule("wait-for-named", false, false, "wait", "If {nurse} cannot take this visit within {minutes} minutes of it reaching her, it waits for her and you are told so. Nobody else is sent."),
            BookingFallbackRule("soonest-automatically", true, false, "soonest", "If {nurse} cannot take this visit within {minutes} minutes of it reaching her, the soonest nurse whose badge is current takes it, and you are told who before she sets off.")
        )
        val choices = listOf(
            BookingFallbackChoice("wait", "Wait for {nurse}", "The visit waits for her, and you are told she has not taken it yet. Nobody else is sent."),
            BookingFallbackChoice("soonest", "The soonest nurse who is free", "The soonest nurse whose badge is current takes it instead, and you are told who before she sets off.")
        )
        const val reviewLabel = "If she cannot take it"
    }

    object Time {
        const val fewerHours = "{nurse} is already booked at some of these hours, so they are not shown. Nothing here is a time she was not offered."
        const val noHoursLeft = "{nurse} has no hour left on this day. Choose another day, or ask for whoever is nearest."
    }

