    const val statusHeading = "Where this booking stands"
    object StatusWords {
        const val reached = "Done"
        const val current = "Now"
        const val waiting = "Not yet"
    }
    const val acceptedBy = "Care's engine is not running, so the simulated roster stands in for it. It accepts a chosen hour at once and says that it did, because a preview that waited for nobody would be a screen that never moves."
    const val asapStaysRequested = "Nobody is looking for a nurse, because nothing is running that could. This visit stays asked for, and the screen says so rather than inventing somebody on the way."

    /** booking.json's own refusals, then the routes' refusals it names, each in the route's words. */
    val refusals = listOf(
        BookingRefusal("confirm-after-cancel", null, null, "A cancelled booking is not confirmed afterwards. Book again if the visit is still wanted."),
        BookingRefusal("confirm-without-a-time", null, null, "Nothing is accepted until there is an hour to hold."),
        BookingRefusal("nurse-badge-not-current", null, null, "A nurse is offered only while her badge is current, so this nurse is not offered."),
        BookingRefusal("slot-not-offered", "POST /v1/access/bookings@2", 409, "That time was not offered, so it cannot be booked."),
        BookingRefusal("service-not-here", "POST /v1/access/bookings@2", 422, "That service is not offered where the visit would be."),
        BookingRefusal("booking-not-found", "GET /v1/access/bookings/{bookingRef}@1", 404, "There is no booking of yours with that reference."),
        BookingRefusal("cancel-after-arrival", "POST /v1/access/bookings/{bookingRef}/cancel@1", 409, "This visit has already started. Speak to the nurse who is with you, or call the Control Tower."),
        BookingRefusal("reason-not-listed", "POST /v1/access/bookings/{bookingRef}/cancel@1", 422, "Choose one of the listed reasons, or say you would rather not."),
        BookingRefusal("thread-closed", "POST /v1/access/visit-threads/{bookingRef}/messages@1", 409, "This visit's thread is closed, so nothing more can be written in it."),
        BookingRefusal("no-attachments", "POST /v1/access/visit-threads/{bookingRef}/messages@1", 422, "A visit thread carries words only. Nothing can be attached."),
        BookingRefusal("not-on-this-visit", "POST /v1/access/visit-threads/{bookingRef}/messages@1", 403, "Only the patient and the nurse on this visit write in its thread."),
        BookingRefusal("message-too-long", "POST /v1/access/visit-threads/{bookingRef}/messages@1", 422, "A message here is kept short. Say the rest to the nurse at the visit."),
        BookingRefusal("no-summary", "POST /v1/access/conversations/{conversationRef}/handover@2", 422, "A handover goes with a structured summary, or it does not go.")
    )

    object Thread {
        const val title = "Messages about this visit"
        const val openLabel = "Messages with your nurse"
        const val lead = "Between you and the nurse on this visit, about getting there and getting in."
        const val notARecord = "These messages are not part of your health record. Anything clinical you want a nurse to know, tell her at the visit, where it is written down properly."
        const val nobodyWatches = "Nobody watches this thread for emergencies. If it cannot wait, call 10177, or 112 from a mobile."
        const val inputLabel = "Message to your nurse"
        const val sendLabel = "Send"
        /** Access's setting visit-thread-max-characters. A proposal nobody has decided. A default an admin may change on the web; this app has no admin surface and uses it as written here. */
        const val maxCharacters = 500
        /** Access's setting visit-thread-open-hours-after-visit. A proposal nobody has decided. A default an admin may change on the web; this app has no admin surface and uses it as written here. */
        const val openHoursAfterVisit = 24
        /** Access's setting visit-thread-photos, which waits on a doctor's clinical review. A proposal nobody has decided. Not clinically reviewed. A default an admin may change on the web; this app has no admin surface and uses it as written here. */
        const val photos = false
        const val empty = "No messages yet. Anything you write stays with this visit."
        const val kept = "Kept with this visit. Not delivered: nothing reaches her phone."
        const val you = "You"
        const val openAfterVisit = "This visit is finished. Its thread stays open for anything that follows from it until {closes}, and then it closes."
        const val wordsOnly = "Words only. Photos and files cannot be sent in this thread."
        const val photosNotInPreview = "Photos are not in this preview yet."
        val closedBecause = listOf(
            BookingThreadClosed("visit-completed", "This visit is finished, so its thread is closed. What was said stays here to read."),
            BookingThreadClosed("booking-cancelled", "This visit was cancelled, so its thread is closed. What was said stays here to read.")
        )
    }

    /** Who answers a GilbertOne handover and when. The emergency numbers are sos.json's and are not a setting. */
    object Handover {
        /** Access's setting handover-answered-by, as vetting.json names the roles. A proposal nobody has decided. A default an admin may change on the web; this app has no admin surface and uses it as written here. */
        val answeredBy = listOf("Registered nurse")
        /** Access's setting handover-hours, in Johannesburg time. A proposal nobody has decided. A default an admin may change on the web; this app has no admin surface and uses it as written here. */
        val hours = listOf(
            HandoverWindow("handover-desk", listOf("mon", "tue", "wed", "thu", "fri", "sat", "sun"), "06:00", "22:00")
        )
        const val answeredByLabel = "Who answers"
        const val outOfHours = "Nobody is on the nurse handover desk now."
        const val outOfHoursNumbers = "If this cannot wait, do not wait for a nurse. Call 10177, or 112 from a mobile."
        const val callback = "A nurse on the desk would call you back when it opens, {when}. In this preview nobody will, because nobody is on the other end."
        const val opensToday = "today at {time}"
        const val opensTomorrow = "tomorrow at {time}"
        const val opensOn = "on {day} at {time}"
